#!/bin/sh
# Генерирует UpdateConfig.swift: репозиторий GitHub (repo.txt) и открытый ключ подписи релизов (pubkey.txt)
HERE="$(cd "$(dirname "$0")" && pwd)"
cat > "$1" <<SW
// generated by release/make_config.sh
enum UpdateConfig {
    static let repo = "$(tr -d '\n ' < "$HERE/repo.txt")"
    static let publicKey = "$(tr -d '\n ' < "$HERE/pubkey.txt")"
}
SW
